<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\Holder\TemplateVersionContentTextAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateVersionContentTextAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TemplateVersionContentTextAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getContentText returns null on a freshly created holder.
     */
    public function testContentTextNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTemplateVersionContentTextAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isContentTextAssigned());
        $this->assertNull($holder->getContentText());
    }
}
class ImplWithTemplateVersionContentTextAttributeHolderUnitTest
{
    use TemplateVersionContentTextAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedContentTextRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultContentText();
    }
}
